// A terminal around the scene it wraps: a prompt above it and a status line
// with the time, the Wi-Fi signal and the battery below it. The prompt opens
// the scene list, settings at its right (or F2) the settings of the scene it
// wraps, and the status line the frame's settings. While the settings show, the
// button is lit, and it (or F2) goes back to the scene.
const pad = (n) => String(n).padStart(2, '0')
const BG = '#0b0f0c'

// The settings of a scene are showing: the built-in scene, its plain id or a
// window of its own (`system/sceneSettings#<scene id>`).
const settingsShow = (frame) => frame.systemScene === true && String(frame.sceneId || '').startsWith('system/sceneSettings')

// The settings of the scene showing, or back to the scene from them: the same
// command both ways (docs/scene-settings.md).
const settings = () => frameos.dispatch('sceneSettings')

export function onEvent(app, context) {
  const key = context.payload || {}
  if (context.event === 'keyDown' && key.key === 'F2' && !key.repeat && !key.alt && !key.ctrl && !key.meta) settings()
  return false
}

function status(frame, now) {
  const parts = [`${pad(now.getHours())}:${pad(now.getMinutes())}`]
  if (typeof frame.wifiRssi === 'number') parts.push(`wifi ${frame.wifiRssi} dBm`)
  if (typeof frame.batteryPercent === 'number') parts.push(`battery ${frame.batteryPercent}%`)
  return parts.join('  |  ')
}

export function get(app) {
  const { hostName, inkColor } = app.state
  const lit = settingsShow(app.frame)
  const now = new Date()
  // The status line changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  return (
    <div className={`flex flex-col w-full h-full p-[1.5vh] bg-[${BG}] text-[${inkColor}] text-[3.2vh]`}>
      <div className="flex items-center h-[6vh] gap-[2vh] min-w-0">
        <div className="flex items-center flex-1 h-full min-w-0" onClick={() => frameos.dispatch('sceneSwitcher', { swap: true })}>
          <span className="truncate">{`${hostName}:~$ show ${app.frame.sceneName || 'scene'}`}</span>
        </div>
        <div
          className={`flex items-center shrink-0 h-full px-[1vh] ${lit ? `bg-[${inkColor}] text-[${BG}]` : `active:bg-[${inkColor}] active:text-[${BG}]`}`}
          onClick={settings}
        >
          <span className={`px-[0.6vh] bg-[${inkColor}] text-[${BG}]`}>F2</span>
          <span className="pl-[0.8vh] whitespace-nowrap">settings</span>
        </div>
      </div>
      <div className={`flex flex-col flex-1 min-h-0 p-[1vh] border border-[${inkColor}]`}>
        <yield />
      </div>
      <div className="flex items-center h-[6vh] min-w-0" onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
        <span className="truncate">{status(app.frame, now)}</span>
      </div>
    </div>
  )
}
